cd /app; python3 - <<'EOF'
p='src/client/content_cao.cpp'
s=open(p).read()
old=s[s.index("		v3f cam_to_entity = m_spritenode->getAbsolutePosition()"):s.index("		// Animation goes downwards\n		row += m_anim_frame;\n\n		float txs")]
new="""		v3f cam_to_entity = m_spritenode->getAbsolutePosition()
				- camera->getAbsolutePosition();
		cam_to_entity.normalize();

		int row = m_tx_basepos.Y;
		int col = m_tx_basepos.X;

		// Yawpitch goes rightwards
		if (m_tx_select_horiz_by_yawpitch) {
			// Express the view direction in the entity's own frame, so that
			// the entity's (absolute) rotation is taken into account.
			// This includes rotations inherited through attachments.
			core::matrix4 rot_mat;
			if (getParent() && m_matrixnode) {
				updatePositionRecursive(m_matrixnode);
				rot_mat = m_matrixnode->getAbsoluteTransformation();
				rot_mat.setTranslation(v3f(0.0f));
			} else {
				setPitchYawRoll(rot_mat, v3f(0.0f, -m_rotation.Y, 0.0f));
			}
			core::matrix4 inv;
			if (!rot_mat.getInverse(inv))
				inv.makeIdentity();
			v3f local = cam_to_entity;
			inv.rotateVect(local);
			local.normalize();

			if (local.Y > 0.75)
				col += 5;
			else if (local.Y < -0.75)
				col += 4;
			else {
				float dir = atan2(local.Z, local.X) / M_PI * 180.;
				dir = wrapDegrees_180(dir);
				if (std::fabs(wrapDegrees_180(dir - 0)) <= 45.1f)
					col += 2;
				else if(std::fabs(wrapDegrees_180(dir - 90)) <= 45.1f)
					col += 3;
				else if(std::fabs(wrapDegrees_180(dir - 180)) <= 45.1f)
					col += 0;
				else if(std::fabs(wrapDegrees_180(dir + 90)) <= 45.1f)
					col += 1;
				else
					col += 4;
			}
		}

"""
s=s.replace(old,new)
open(p,'w').write(s)
